## Campos de un RosMsg, portable rclgd (dinámico o tipado) ↔ ros2_vita (dinámico).
const _OMITIR := {"script": true}
const _NO_CAMPO := PROPERTY_USAGE_CATEGORY | PROPERTY_USAGE_GROUP | PROPERTY_USAGE_SUBGROUP
static var _cache := {}   # "pkg/msg/T" -> PackedStringArray

## Lista de campos de un tipo; se calcula UNA vez sobre un prototipo vacío (arrays vacíos:
## en rclgd get_property_list() convierte cada miembro, ros_msg.cpp:296-300).
static func campos_de_tipo(tipo: String) -> PackedStringArray:
	if _cache.has(tipo):
		return _cache[tipo]
	var out := PackedStringArray()
	var proto = RosMsg.from_type(tipo)
	if proto == null:
		return out   # tipo desconocido (sin typesupport en el PC / sin .rsch en la Vita)
	var clase: String = proto.get_class()
	var lista: Array = ClassDB.class_get_property_list(clase, true) if clase != "RosMsg" \
			else proto.get_property_list()
	for p in lista:
		if p.usage & _NO_CAMPO or _OMITIR.has(p.name):
			continue
		out.append(p.name)
	_cache[tipo] = out
	return out

static func campos(msg) -> PackedStringArray:
	return campos_de_tipo(msg.get_ros_interface_name())

## Ruta ya troceada: ["twist", "twist", "linear", "x"] o ["poses", "3", "pose"].
static func leer_ruta(msg, ruta: PackedStringArray):
	var v = msg
	for paso in ruta:
		if v is RosMsg:
			v = v.get_member(StringName(paso))
		elif typeof(v) >= TYPE_ARRAY and paso.is_valid_int() and paso.to_int() < v.size():
			v = v[paso.to_int()]
		else:
			return null
	return v

extends Node
## VisorRos: contexto compartido de los displays (equivale a rviz_common::DisplayContext).
const Contexto = preload("res://comun/ros/contexto_ros.gd")
@export var frame_fijo := "map"
@export var nombre_nodo := "visor"
@export var transporte := ""          # "" = el de la plataforma
var contexto = Contexto.new()
var en_vita := OS.has_feature("vita")
var tf = null                          # RosTfListener solo en rclgd: sin anotar el tipo (no existe en la Vita)

func _ready() -> void:
	if contexto.iniciar(nombre_nodo, "", transporte) != OK:
		push_error("VisorRos: no arranca ROS")
		return
	if contexto.nodo.has_method("create_tf_listener"):
		tf = contexto.nodo.call("create_tf_listener", 10.0)
	# Los hijos ya están listos (_ready va de hojas a raíz): se conectan aquí.
	for d in get_tree().get_nodes_in_group("display_ros"):
		if is_ancestor_of(d):
			d.conectar(self)

## Pose de `frame` en el frame fijo, convención Godot; null si TF no la conoce aún.
func transformada(frame: String):
	if frame == "" or frame == frame_fijo:
		return Transform3D.IDENTITY
	if tf == null or not tf.can_transform(frame_fijo, frame):
		return null
	return tf.lookup_transform(frame_fijo, frame)

func _exit_tree() -> void:
	tf = null
	contexto.cerrar()

