## Base de los displays 3D (las de 2D y HUD son idénticas salvo `extends`). Subclases: _procesar/_caducar.
const Canal = preload("res://comun/visor/canal_display.gd")
@export var habilitado := true
@export var topic := ""
@export var tipo := ""
@export var frame_id := ""            # "" = header.frame_id del mensaje
@export var hz_max := 15.0                   # hz_max_vita: el de la Vita (0 = el mismo)
@export var hz_max_vita := 5.0
@export var best_effort := true              # profundidad: KEEP_LAST n
@export var profundidad := 1
@export var decaimiento_s := 0.0      # 0 = el último dato no caduca
@export var solo_pc := false
var visor
var canal = Canal.new()
var estado := "sin conectar"
func _enter_tree() -> void:
	add_to_group("display_ros")
func conectar(v) -> void:
	visor = v
	if not habilitado or (solo_pc and v.en_vita) or topic == "":
		visible = false
		return
	canal.hz_max = hz_max_vita if v.en_vita and hz_max_vita > 0.0 else hz_max
	canal.mensaje.connect(_al_mensaje)
	estado = "ok" if canal.abrir(v.contexto.nodo, topic, tipo, v.contexto.qos(best_effort, profundidad)) else "error al suscribir"
func _process(_dt: float) -> void:
	canal.bombear()
	if canal.caducado(decaimiento_s): _caducar()
func _al_mensaje(msg) -> void:
	var f := frame_id
	if f == "" and "header" in msg: f = msg.header.frame_id
	var t = visor.transformada(f)
	if t == null:
		estado = "sin TF %s→%s" % [f, visor.frame_fijo]
		return
	transform = t
	_procesar(msg)
func _procesar(_msg) -> void: pass     # = processMessage()
func _caducar() -> void: visible = false

