## Inspector genérico (rqt_topic / ros2 topic echo) para CUALQUIER RosMsg. Solo PC (coste de glifos en la Vita).
const Intro = preload("res://comun/visor/introspeccion_ros.gd")
@export var limite_array := 32
@export var hz_refresco := 5.0
var _filas := {}              # ruta -> TreeItem
var _msg = null
var _t := 0.0
func _ready() -> void:
	columns = 2; create_item().set_text(0, "(esperando mensajes)")
func mostrar(msg) -> void:     # conectar a canal.mensaje
	_msg = msg
func _process(dt: float) -> void:
	_t += dt
	if _msg == null or _t < 1.0 / hz_refresco: return
	_t = 0.0
	get_root().set_text(0, _msg.get_ros_interface_name())
	_rellenar(get_root(), _msg, "")
	_msg = null
func _rellenar(padre: TreeItem, v, ruta: String) -> void:
	var claves: Array = Array(Intro.campos(v)) if v is RosMsg else range(mini(v.size(), limite_array))
	for c in claves:
		var hijo = v.get_member(c) if v is RosMsg else v[c]
		_fila(padre, "%s/%s" % [ruta, c], str(c) if v is RosMsg else "[%d]" % c, hijo)
	if not v is RosMsg:
		_fila(padre, ruta + "/…", "…", "%d elementos" % v.size()).visible = v.size() > limite_array
func _fila(padre: TreeItem, ruta: String, nombre: String, v) -> TreeItem:
	var it: TreeItem = _filas.get(ruta)
	if it == null:
		it = create_item(padre)
		it.set_text(0, nombre)
		it.collapsed = true
		_filas[ruta] = it
	var compuesto: bool = v is RosMsg or (typeof(v) >= TYPE_ARRAY and typeof(v) != TYPE_PACKED_BYTE_ARRAY)
	it.set_text(1, "" if v is RosMsg else ("%s[%d]" % [type_string(typeof(v)), v.size()] if typeof(v) >= TYPE_ARRAY
			else ("%.4f" % v if v is float else str(v))))
	if compuesto and not it.collapsed:
		_rellenar(it, v, ruta)      # perezoso: solo lo desplegado
	return it

extends Control
## Inspector compacto (Vita y PC): filas planas dibujadas con draw_string, ≤ 4 Hz, solo si cambian.
const Intro = preload("res://comun/visor/introspeccion_ros.gd")
@export var filas := 12
@export var ancho_max := 32
@export var hz_refresco := 4.0
var desplegados := {}          # ruta -> true
var _lineas := PackedStringArray()
var _primera := 0
var _msg = null
var _t := 0.0
func mostrar(msg) -> void:
	_msg = msg
func _process(dt: float) -> void:
	_t += dt
	if _msg == null or _t < 1.0 / hz_refresco:
		return
	_t = 0.0
	var nuevas := PackedStringArray()
	_aplanar(_msg, "", 0, nuevas)
	_msg = null
	if nuevas != _lineas:
		_lineas = nuevas
		queue_redraw()
func _aplanar(m, ruta: String, nivel: int, out: PackedStringArray) -> void:
	for c in Intro.campos(m):
		var v = m.get_member(c)
		var r := ruta + "/" + c
		out.append(("  ".repeat(nivel) + "%s: %s" % [c, _corto(v)]).left(ancho_max))
		if v is RosMsg and desplegados.has(r):
			_aplanar(v, r, nivel + 1, out)
func _corto(v) -> String:
	if v is RosMsg: return "{…}"
	if typeof(v) >= TYPE_ARRAY: return "%s[%d] %s" % [type_string(typeof(v)), v.size(), str(v.slice(0, 4))]
	return "%.3f" % v if v is float else str(v)
func _draw() -> void:
	var f := get_theme_default_font()
	for i in mini(filas, _lineas.size() - _primera):
		draw_string(f, Vector2(4, 16 + 16 * i), _lineas[_primera + i])

