## Trazador de series (rqt_plot/Foxglove Plot). Rutas «/topic.campo.sub[i]». Sin bucles por punto al dibujar.
const Intro = preload("res://comun/visor/introspeccion_ros.gd")
@export var ventana_s := 10.0
@export var capacidad := 300
@export var colores := PackedColorArray([Color.ORANGE, Color.CYAN, Color.LIME])
var series := []              # {campos, pts: PackedVector2Array, cab, n}
var _y_min := INF; var _y_max := -INF; var _sucio := false
static func trocear(ruta: String) -> Array:     # "/odom.pose.pose.position.x" -> ["/odom", [...]]
	var i := ruta.find(".")
	return [ruta.left(i), ruta.substr(i + 1).replace("[", ".").replace("]", "").split(".")]
func anadir_serie(ruta: String) -> int:
	var pts := PackedVector2Array()
	pts.resize(capacidad)
	series.append({"campos": trocear(ruta)[1], "pts": pts, "cab": 0, "n": 0})
	return series.size() - 1
func al_mensaje(i: int, msg) -> void:           # conectar con canal.mensaje.connect(al_mensaje.bind(i))
	var v = Intro.leer_ruta(msg, series[i].campos)
	if not (v is float or v is int or v is bool): return
	var s = series[i]
	var y := float(v)
	s.pts[s.cab] = Vector2(Time.get_ticks_msec() * 0.001, y)
	s.cab = (s.cab + 1) % capacidad
	s.n = mini(s.n + 1, capacidad)
	_y_min = minf(_y_min, y); _y_max = maxf(_y_max, y); _sucio = true
func _process(_dt: float) -> void:
	if _sucio: _sucio = false; queue_redraw()
func _draw() -> void:
	var ahora := Time.get_ticks_msec() * 0.001
	var esc := Vector2(size.x / ventana_s, -size.y / maxf(_y_max - _y_min, 1e-6))
	draw_set_transform(Vector2(size.x - ahora * esc.x, size.y - _y_min * esc.y), 0.0, esc)
	for k in series.size():
		var s = series[k]
		var orden: PackedVector2Array = s.pts.slice(s.cab) + s.pts.slice(0, s.cab) if s.n == capacidad else s.pts.slice(0, s.n)
		if orden.size() > 1:
			draw_polyline(orden, colores[k % colores.size()], -1.0)

extends RefCounted
## Explorador de topics: grafo en el PC; catálogo del relay o estático en la Vita (misma salida).
signal topic_nuevo(topic: String, tipo: String)
signal topic_perdido(topic: String)
var topics := {}               # topic -> tipo (el primero si hay varios)
var _nodo

func _init(nodo) -> void:
	_nodo = nodo

func tiene_grafo() -> bool:
	return _nodo.has_method("get_topic_names_and_types")

## Llamar con un RosTimer de 2 s (o al pulsar «refrescar»).
func sondear() -> void:
	if not tiene_grafo():
		return                 # en la Vita lo alimenta aplicar_catalogo()
	aplicar(_nodo.call("get_topic_names_and_types"))

func aplicar(grafo: Dictionary) -> void:
	var vistos := {}
	for t in grafo:
		var tipos: Array = grafo[t]
		if tipos.is_empty():
			continue
		vistos[t] = tipos[0]
		if not topics.has(t):
			topics[t] = tipos[0]
			topic_nuevo.emit(t, tipos[0])
	for t in topics.keys():
		if not vistos.has(t):
			topics.erase(t)
			topic_perdido.emit(t)

func publicadores(topic: String) -> int:
	return _nodo.call("count_publishers", topic) if tiene_grafo() else -1

## Cliente del catálogo (Vita y PC). Formato de /vita/catalogo: "v1\n<topic> <tipo>\n…"
## Suscripción: contexto.nodo.create_subscription(prefijo + "/catalogo", "std_msgs/msg/String",
##     _al_catalogo, contexto.qos(false, 1, true))   # fiable + TRANSIENT_LOCAL (como joints_orden)
var explorador                 # explorador_topics.gd
var solo_decodificables := true

func _al_catalogo(msg) -> void:
	var lineas: PackedStringArray = String(msg.data).split("\n", false)
	if lineas.is_empty() or lineas[0] != "v1":
		push_warning("catálogo: versión desconocida")
		return
	var grafo := {}
	for i in range(1, lineas.size()):
		var partes := lineas[i].split(" ", false)
		if partes.size() < 2:
			continue
		if not solo_decodificables or _decodificable(partes[1]):
			grafo[partes[0]] = [partes[1]]
	explorador.aplicar(grafo)

var _decod := {}
func _decodificable(tipo: String) -> bool:   # portable: from_type da null sin .rsch/typesupport
	if not _decod.has(tipo):
		_decod[tipo] = RosMsg.from_type(tipo) != null
	return _decod[tipo]

## Respaldo sin relay: res://ros/catalogo.json = {"/odom": ["nav_msgs/msg/Odometry"], …}
func catalogo_estatico() -> void:
	var f := FileAccess.open("res://ros/catalogo.json", FileAccess.READ)
	if f:
		explorador.aplicar(JSON.parse_string(f.get_as_text()))

