## Display de reserva para un tipo que la Vita no puede decodificar (sin .rsch) o sin display propio.
@export var etiqueta: Label

func conectar(v) -> void:
	var decodificable := RosMsg.from_type(tipo) != null     # null si no está en el esquema (igual que rclgd)
	if not decodificable:
		etiqueta.text = "%s\n%s\nsin esquema: añadir a generar_esquemas.py" % [topic, tipo]
		return                     # no suscribir: cada muestra daría ERR_FAIL_COND en ros_runtime.cpp:123
	super.conectar(v)

