	etiqueta.text = "%s  %.1f Hz\n%s" % [topic, canal.hz_medido, str(msg).left(200)]

extends "res://comun/visor/display_ros_hud.gd"
## Valor escalar de std_msgs (Bool, Int*, UInt*, Float*, Byte, Char, String, Empty).
@export var etiqueta: Label
@export var indicador: ColorRect        # opcional, para Bool
@export var unidad := ""
@export var decimales := 3
var eventos := 0                         # para std_msgs/Empty

func _procesar(msg) -> void:
	if tipo == "std_msgs/msg/Empty":
		eventos += 1
		etiqueta.text = "%s: %d eventos" % [topic, eventos]
		return
	var v = msg.data
	var txt := str(v)
	if v is float:
		txt = String.num(v, decimales)
	elif v is bool and indicador:
		indicador.color = Color.LIME_GREEN if v else Color.DARK_RED
	elif tipo == "std_msgs/msg/Char":
		txt = "%d '%s'" % [v, String.chr(v)]
	elif v is String:
		txt = v.left(64)
	var nuevo := "%s: %s %s" % [topic.get_file(), txt, unidad]
	if nuevo != etiqueta.text:           # no rehacer glifos si no cambia (doc 34)
		etiqueta.text = nuevo

func _caducar() -> void:
	etiqueta.modulate = Color(1, 1, 1, 0.4)   # dato viejo: atenuado en vez de ocultar

extends "res://comun/visor/display_ros_hud.gd"
## Cualquier *MultiArray: perfil 1D (polilínea fina) o mapa de calor 2D (textura).
@export var max_puntos := 128
@export var mapa: TextureRect           # en la escena; solo se usa con 2 dimensiones
var _pts := PackedVector2Array()
var _min := 0.0
var _max := 1.0

func _procesar(msg) -> void:
	var dims: Array = msg.layout.dim
	var d = msg.data
	if dims.size() == 2 and mapa:
		_calor(d, int(dims[0].size), int(dims[1].size), int(msg.layout.data_offset))
		return
	var paso := maxi(1, ceili(d.size() / float(max_puntos)))
	_pts.resize(ceili(d.size() / float(paso)))
	_min = INF
	_max = -INF
	for i in _pts.size():                 # bucle GDScript: acotado por max_puntos
		var y := float(d[i * paso])
		_pts[i] = Vector2(i * paso, y)
		_min = minf(_min, y)
		_max = maxf(_max, y)
	queue_redraw()

func _draw() -> void:
	if _pts.size() < 2:
		return
	var esc := Vector2(size.x / maxf(_pts[-1].x, 1.0), -size.y / maxf(_max - _min, 1e-6))
	draw_set_transform(Vector2(0, size.y - _min * esc.y), 0.0, esc)
	draw_polyline(_pts, Color.ORANGE, -1.0)

func _calor(d, filas: int, cols: int, ofs: int) -> void:
	var bytes: PackedByteArray = d.slice(ofs, ofs + filas * cols) if d is PackedByteArray else PackedByteArray()
	if bytes.size() == filas * cols:      # UInt8: directo; otros tipos: normalizar a 0–255 en el PC/relay
		mapa.texture = ImageTexture.create_from_image(Image.create_from_data(cols, filas, false, Image.FORMAT_L8, bytes))

extends "res://comun/visor/display_ros_hud.gd"
## std_msgs/ColorRGBA: muestra de color. `color_ros` la reutilizan Marker y MarkerArray.
@export var muestra: ColorRect
@export var etiqueta: Label

static func color_ros(c) -> Color:
	return Color(c.r, c.g, c.b, c.a)

## Índice en una paleta de N colores (textura-paleta de ADR 0011 §3), por distancia RGB.
static func indice_paleta(c: Color, paleta: PackedColorArray) -> int:
	var mejor := 0
	var dmin := INF
	for i in paleta.size():
		var p := paleta[i]
		var d := Vector3(p.r - c.r, p.g - c.g, p.b - c.b).length_squared()
		if d < dmin:
			dmin = d
			mejor = i
	return mejor

func _procesar(msg) -> void:
	var c := color_ros(msg)
	muestra.color = c
	etiqueta.text = "#" + c.to_html(true)

extends Label
## Monitor de topics de un VisorRos (Hz, recibidos/mostrados, latencia, estado). Refresco 2 Hz.
const Tiempo = preload("res://comun/visor/tiempo_ros.gd")
@export var visor: Node
var _t := 0.0

func _process(dt: float) -> void:
	_t += dt
	if _t < 0.5 or visor == null:
		return
	_t = 0.0
	var lineas := PackedStringArray()
	for d in visor.get_tree().get_nodes_in_group("display_ros"):
		if not visor.is_ancestor_of(d) or d.topic == "":
			continue
		lineas.append("%-18s %5.1f Hz %s" % [d.topic.right(18), d.canal.hz_medido, d.estado])
	if rclgd.has_method("get_transport_info"):   # solo ros2_vita
		var info: Dictionary = rclgd.call("get_transport_info")
		lineas.append("xrce: %s" % str(info).left(60))
	var nuevo := "\n".join(lineas)
	if nuevo != text:
		text = nuevo

// Esbozo C++ (ros2_vita/ros_runtime.cpp) de P1: coalescer por suscripción ANTES de decodificar.
// Hoy: deliver() decodifica cada RxItem (ros_runtime.cpp:118-133) y process_frame entrega todos (:496-511).
void RosSubscriber::deliver(const uint8_t *p_data, size_t p_len) {
	if (!callback.is_valid()) {
		return;
	}
	uint64_t now = OS::get_singleton()->get_ticks_usec();
	stats_samples++;                       // P2: contadores (get_stats() -> Dictionary)
	stats_bytes += p_len;
	if (min_period_us && now - last_usec < min_period_us) {
		return;                            // set_max_rate(hz): descartar SIN decodificar
	}
	if (type_idx == MSG_SCHEMA_NO_TYPE) {   // P1: resuelto una vez en setup(), no por mensaje
		stats_no_schema++;
		return;
	}
	last_usec = now;
	Ref<RosMsg> msg;
	msg.instantiate();
	msg->set_type_index_only(type_idx);     // sin construir valores por defecto
	if (msg->deserialize(PackedByteArray(...)) != OK) {
		stats_cdr_errors++;
		return;
	}
	callback.call(msg);
}
// Mejor aún (coalescer): en process_frame, si dos RxItem son del mismo sub_id, quedarse con el último
// cuando el suscriptor lo pide (latest_only), igual que hace canal_display.gd pero sin pagar el decode.
